Item.method_code:
Innovator innovator = this.getInnovator();
string fileIdsString = this.getAttribute("idlist") ?? string.Empty;
var fileIds = fileIdsString.Split(",", StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries);
Newtonsoft.Json.Linq.JObject result = new Newtonsoft.Json.Linq.JObject();

if (fileIds.Length == 0)
{
	result["value"] = new Newtonsoft.Json.Linq.JArray();
	return innovator.newResult(Newtonsoft.Json.JsonConvert.SerializeObject(result));
}

string useTokenString = this.getProperty("useToken", "true");
var fileUrls = serverConnection.getFileUrls(new ArrayList(fileIds), useTokenString == "true" ? Aras.IOM.UrlType.SecurityToken : Aras.IOM.UrlType.None, Aras.IOM.VaultUrlType.External);

Newtonsoft.Json.Linq.JArray resultArray = new Newtonsoft.Json.Linq.JArray();
for (int i = 0; i < fileIds.Length; i++)
{
	Newtonsoft.Json.Linq.JObject item = new Newtonsoft.Json.Linq.JObject();
	item["url"] = fileUrls[i].ToString();
	item["id"] = fileIds[i].ToString();
	resultArray.Add(item);
}

result["value"] = resultArray;
return innovator.newResult(Newtonsoft.Json.JsonConvert.SerializeObject(result));
